package com.mygame.core;

import com.badlogic.gdx.Input;
import com.badlogic.gdx.backends.headless.mock.input.MockInput;
import java.util.List;
import java.util.ArrayList;

public class GameInput extends MockInput {
    private final List<String> commands;
    private int currentIndex = -1;
    private String currentCommand = null;
    private int currentKey = -1;

    public GameInput(List<String> commands) {
        this.commands = new ArrayList<>(commands);
    }

    public boolean hasNext() {
        return currentIndex + 1 < commands.size();
    }

    public void tick() {
        currentIndex++;
        if (currentIndex < commands.size()) {
            currentCommand = commands.get(currentIndex);
            currentKey = commandToKey(currentCommand);
        } else {
            currentCommand = null;
            currentKey = -1;
        }
    }

    public String getCurrentCommand() {
        return currentCommand;
    }

    public boolean isExhausted() {
        return currentIndex >= commands.size() - 1;
    }

    private int commandToKey(String cmd) {
        if (cmd == null) return -1;
        switch (cmd) {
            case "N": return Keys.UP;
            case "S": return Keys.DOWN;
            case "E": return Keys.RIGHT;
            case "W": return Keys.LEFT;
            case "PICK": return Keys.SPACE;
            case "QUIT": return Keys.ESCAPE;
            default: return -1;
        }
    }

    @Override
    public boolean isKeyPressed(int key) {
        return currentKey != -1 && key == currentKey;
    }

    @Override
    public boolean isKeyJustPressed(int key) {
        return currentKey != -1 && key == currentKey;
    }
}

package com.mygame.core;

import java.util.ArrayList;
import java.util.List;

public class GameMap {
    public final int width;
    public final int height;
    public final int playerStartX;
    public final int playerStartY;
    public final List<Item> items;

    public GameMap(int width, int height, int playerStartX, int playerStartY, List<Item> items) {
        this.width = width;
        this.height = height;
        this.playerStartX = playerStartX;
        this.playerStartY = playerStartY;
        this.items = items;
    }

    public static class Item {
        public final int x;
        public final int y;
        public final String name;
        public boolean pickedUp = false;

        public Item(int x, int y, String name) {
            this.x = x;
            this.y = y;
            this.name = name;
        }
    }
}

package com.mygame.core;

import com.badlogic.gdx.files.FileHandle;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

public class MapParser {
    public static GameMap parse(FileHandle fileHandle) throws IOException {
        List<String> tokens = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(fileHandle.read(), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty() || line.startsWith("#")) {
                    continue;
                }
                String[] parts = line.split("\\s+");
                for (String part : parts) {
                    if (!part.isEmpty()) {
                        tokens.add(part);
                    }
                }
            }
        }

        if (tokens.size() < 5) {
            throw new IllegalArgumentException("Invalid map file: too few tokens");
        }

        int width = Integer.parseInt(tokens.get(0));
        int height = Integer.parseInt(tokens.get(1));
        int playerStartX = Integer.parseInt(tokens.get(2));
        int playerStartY = Integer.parseInt(tokens.get(3));
        int itemCount = Integer.parseInt(tokens.get(4));

        List<GameMap.Item> items = new ArrayList<>();
        int index = 5;
        for (int i = 0; i < itemCount; i++) {
            if (index + 2 >= tokens.size()) {
                throw new IllegalArgumentException("Invalid map file: missing item tokens at index " + index);
            }
            int x = Integer.parseInt(tokens.get(index++));
            int y = Integer.parseInt(tokens.get(index++));
            String name = tokens.get(index++);
            items.add(new GameMap.Item(x, y, name));
        }

        return new GameMap(width, height, playerStartX, playerStartY, items);
    }
}

package com.mygame.core;

import com.badlogic.gdx.ApplicationListener;
import com.badlogic.gdx.Gdx;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;

public class GameListener implements ApplicationListener {
    private final String mapPath;
    private final String commandsPath;
    private final String transcriptPath;
    private final CountDownLatch latch;

    private GameMap gameMap;
    private int playerX;
    private int playerY;
    private List<String> inventory;
    private StringBuilder transcript;
    private int turnCount;

    public GameListener(String mapPath, String commandsPath, String transcriptPath, CountDownLatch latch) {
        this.mapPath = mapPath;
        this.commandsPath = commandsPath;
        this.transcriptPath = transcriptPath;
        this.latch = latch;
    }

    @Override
    public void create() {
        try {
            gameMap = MapParser.parse(Gdx.files.absolute(mapPath));
            playerX = gameMap.playerStartX;
            playerY = gameMap.playerStartY;
        } catch (IOException e) {
            throw new RuntimeException("Failed to parse map file: " + mapPath, e);
        }
        inventory = new ArrayList<>();
        transcript = new StringBuilder();
        turnCount = 0;
    }

    @Override
    public void resize(int width, int height) {
    }

    @Override
    public void render() {
        try {
            GameInput input = (GameInput) Gdx.input;
            if (input == null) return;

            input.tick();
            String cmd = input.getCurrentCommand();

            if (cmd == null) {
                if (turnCount == 0) {
                    writeFinalAndExit();
                }
                return;
            }

            turnCount++;
            processCommand();

            appendTurnTranscript(turnCount, cmd);

            if (cmd.equals("QUIT") || input.isExhausted()) {
                writeFinalAndExit();
            }
        } catch (Throwable t) {
            t.printStackTrace();
            latch.countDown();
            Gdx.app.exit();
        }
    }

    private void processCommand() {
        if (Gdx.input.isKeyJustPressed(com.badlogic.gdx.Input.Keys.UP)) {
            if (playerY + 1 < gameMap.height) {
                playerY++;
            }
        } else if (Gdx.input.isKeyJustPressed(com.badlogic.gdx.Input.Keys.DOWN)) {
            if (playerY - 1 >= 0) {
                playerY--;
            }
        } else if (Gdx.input.isKeyJustPressed(com.badlogic.gdx.Input.Keys.RIGHT)) {
            if (playerX + 1 < gameMap.width) {
                playerX++;
            }
        } else if (Gdx.input.isKeyJustPressed(com.badlogic.gdx.Input.Keys.LEFT)) {
            if (playerX - 1 >= 0) {
                playerX--;
            }
        } else if (Gdx.input.isKeyJustPressed(com.badlogic.gdx.Input.Keys.SPACE)) {
            for (GameMap.Item item : gameMap.items) {
                if (item.x == playerX && item.y == playerY && !item.pickedUp) {
                    item.pickedUp = true;
                    inventory.add(item.name);
                    break;
                }
            }
        } else if (Gdx.input.isKeyJustPressed(com.badlogic.gdx.Input.Keys.ESCAPE)) {
            // QUIT - no-op for position/inventory
        }
    }

    private void appendTurnTranscript(int turn, String cmd) {
        String invStr = String.join(",", inventory);
        transcript.append("turn=").append(turn)
                  .append(" cmd=").append(cmd)
                  .append(" pos=").append(playerX).append(",").append(playerY)
                  .append(" inv=").append(invStr)
                  .append("\n");
    }

    private void writeFinalAndExit() {
        String invStr = String.join(",", inventory);
        transcript.append("FINAL pos=").append(playerX).append(",").append(playerY)
                  .append(" inv=").append(invStr)
                  .append(" turns=").append(turnCount)
                  .append("\n");

        try {
            Gdx.files.absolute(transcriptPath).writeString(transcript.toString(), false, "UTF-8");
        } catch (Exception e) {
            e.printStackTrace();
        }

        Gdx.app.exit();
        latch.countDown();
    }

    @Override
    public void pause() {
    }

    @Override
    public void resume() {
    }

    @Override
    public void dispose() {
    }
}

package com.mygame.headless;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;
import com.mygame.core.GameInput;
import com.mygame.core.GameListener;

import java.io.BufferedReader;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;

public class HeadlessLauncher {
    public static void main(String[] args) {
        String mapPath = null;
        String commandsPath = null;
        String transcriptPath = null;

        for (String arg : args) {
            if (arg.startsWith("--map=")) {
                mapPath = arg.substring("--map=".length());
            } else if (arg.startsWith("--commands=")) {
                commandsPath = arg.substring("--commands=".length());
            } else if (arg.startsWith("--transcript=")) {
                transcriptPath = arg.substring("--transcript=".length());
            }
        }

        if (mapPath == null || commandsPath == null || transcriptPath == null) {
            System.err.println("Error: Missing required arguments.");
            System.err.println("Usage: --map=<absolute_path> --commands=<absolute_path> --transcript=<absolute_path>");
            System.exit(1);
        }

        CountDownLatch latch = new CountDownLatch(1);
        GameListener listener = new GameListener(mapPath, commandsPath, transcriptPath, latch);

        HeadlessApplicationConfiguration config = new HeadlessApplicationConfiguration();
        config.updatesPerSecond = 1000;

        try {
            HeadlessApplication app = new HeadlessApplication(listener, config);

            List<String> commands = readCommands(commandsPath);
            GameInput gameInput = new GameInput(commands);
            Gdx.input = gameInput;

            latch.await();
        } catch (Throwable t) {
            t.printStackTrace();
            System.exit(1);
        }

        System.exit(0);
    }

    private static List<String> readCommands(String path) throws IOException {
        List<String> commands = new ArrayList<>();
        File file = new File(path);
        if (!file.exists()) {
            throw new FileNotFoundException("Commands file not found: " + path);
        }
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(file), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty() || line.startsWith("#")) {
                    continue;
                }
                commands.add(line);
            }
        }
        return commands;
    }
}
